import{_ as a,c as o,o as d,a5 as t}from"./chunks/framework.DuCYAsAJ.js";const m=JSON.parse('{"title":"Ticketmaster 票务系统设计","description":"","frontmatter":{"title":"Ticketmaster 票务系统设计","date":"2026-05-02T00:00:00.000Z","order":10},"headers":[],"relativePath":"posts/SystemDesign/ticketmaster.md","filePath":"posts/SystemDesign/ticketmaster.md","lastUpdated":1779463578000}'),c={name:"posts/SystemDesign/ticketmaster.md"};function i(r,e,l,s,n,h){return d(),o("div",null,[...e[0]||(e[0]=[t('<h2 id="ticketmaster-票务系统设计" tabindex="-1">Ticketmaster 票务系统设计 <a class="header-anchor" href="#ticketmaster-票务系统设计" aria-label="Permalink to &quot;Ticketmaster 票务系统设计&quot;">​</a></h2><p>本文设计的是一个类似 Ticketmaster 的在线票务系统。用户需要能浏览演出、搜索活动，并在高并发场景下安全地购买门票。它最核心的矛盾不是“怎么展示活动列表”，而是如何在热门抢票时既不超卖，又不让体验变得混乱。因此，系统主线可以拆成三条：读路径要能扛住热门活动的超高访问量；写路径要保证绝不 double booking；极端热点活动要有比“所有人一起抢座位”更好的体验策略。</p><h3 id="问题定义与边界" tabindex="-1">问题定义与边界 <a class="header-anchor" href="#问题定义与边界" aria-label="Permalink to &quot;问题定义与边界&quot;">​</a></h3><h4 id="功能需求" tabindex="-1">功能需求 <a class="header-anchor" href="#功能需求" aria-label="Permalink to &quot;功能需求&quot;">​</a></h4><p>用户能够查看活动详情；用户能够搜索活动；用户能够购买活动门票。</p><h4 id="非功能需求" tabindex="-1">非功能需求 <a class="header-anchor" href="#非功能需求" aria-label="Permalink to &quot;非功能需求&quot;">​</a></h4><ol><li>查看和搜索应优先可用性</li><li>购票应优先一致性，不能重复售卖同一张票</li><li>搜索延迟应尽量低，目标可收敛在 <code>&lt; 500ms</code></li><li>系统整体是明显的读多写少，大约可按 <code>100:1</code> 理解</li><li>系统需要能处理极端热门活动，例如单场活动 <code>10M</code> 用户同时关注</li></ol><h4 id="本文暂不展开" tabindex="-1">本文暂不展开 <a class="header-anchor" href="#本文暂不展开" aria-label="Permalink to &quot;本文暂不展开&quot;">​</a></h4><p>用户查看已购订单、活动主办方后台、动态定价、退款、转售、黄牛对抗。</p><h3 id="核心实体、接口与数据模型" tabindex="-1">核心实体、接口与数据模型 <a class="header-anchor" href="#核心实体、接口与数据模型" aria-label="Permalink to &quot;核心实体、接口与数据模型&quot;">​</a></h3><h4 id="核心实体" tabindex="-1">核心实体 <a class="header-anchor" href="#核心实体" aria-label="Permalink to &quot;核心实体&quot;">​</a></h4><p>核心实体包括 <code>Event</code>、<code>Performer</code>、<code>Venue</code>、<code>Ticket</code>、<code>Booking</code> 和 <code>User</code>。其中最值得先讲清楚的是 <code>Venue</code> 和 <code>Ticket</code> 的关系：<code>Venue</code> 保存场馆和 seat map，<code>Ticket</code> 表示某场活动里某个座位对应的一张可售票。也就是说，当一个活动创建出来时，系统会基于 Venue 的座位图，为这个活动实例化出一批 <code>Ticket</code>。</p><h4 id="初始接口" tabindex="-1">初始接口 <a class="header-anchor" href="#初始接口" aria-label="Permalink to &quot;初始接口&quot;">​</a></h4><ul><li>查看活动：<code>GET /events/{eventId}</code></li><li>搜索活动：<code>GET /events/search?keyword={keyword}&amp;start={start}&amp;end={end}&amp;pageSize={n}&amp;page={p}</code></li><li>下单购票：<code>POST /bookings/{eventId}</code></li></ul><p>初始购票接口可以简单设计成 <code>{ &quot;ticketIds&quot;: [...], &quot;paymentDetails&quot;: {} }</code>，这只是一个起点。随着系统深入，我们会把“直接购票”进一步拆成先保留 / 预占座位，再支付确认。</p><h4 id="基础数据模型" tabindex="-1">基础数据模型 <a class="header-anchor" href="#基础数据模型" aria-label="Permalink to &quot;基础数据模型&quot;">​</a></h4><p><code>Event</code> 包含 <code>eventId</code>、<code>venueId</code>、<code>performerId</code>、<code>startTime</code>、<code>description</code>。<code>Ticket</code> 包含 <code>ticketId</code>、<code>eventId</code>、<code>section</code>、<code>row</code>、<code>seat</code>、<code>price</code>、<code>status</code>、<code>bookingId</code>、<code>reservationExpiresAt</code>。<code>Booking</code> 包含 <code>bookingId</code>、<code>userId</code>、<code>ticketIds</code>、<code>totalPrice</code>、<code>status</code>。这里 <code>Ticket.status</code> 通常至少会演进成三态：<code>available</code>、<code>reserved</code>、<code>sold</code>。</p><h3 id="核心架构设计" tabindex="-1">核心架构设计 <a class="header-anchor" href="#核心架构设计" aria-label="Permalink to &quot;核心架构设计&quot;">​</a></h3><h4 id="一、用户能够查看活动" tabindex="-1">一、用户能够查看活动 <a class="header-anchor" href="#一、用户能够查看活动" aria-label="Permalink to &quot;一、用户能够查看活动&quot;">​</a></h4><p>查看链路可以先保持直接：客户端请求 <code>GET /events/{eventId}</code>，API Gateway 转给 <code>Event Service</code>，<code>Event Service</code> 从数据库读取活动、场馆、艺人和票务状态，返回给客户端渲染活动页和 seat map。这条链路本质上是读路径，没有强一致性压力，它的重点是响应要快，热门活动时要能扛住高并发刷新。</p><h4 id="二、用户能够搜索活动" tabindex="-1">二、用户能够搜索活动 <a class="header-anchor" href="#二、用户能够搜索活动" aria-label="Permalink to &quot;二、用户能够搜索活动&quot;">​</a></h4><p>第一版搜索可以先做一个基础的 <code>Search Service</code>，让它根据关键词、日期、地点去查询活动数据。这一步作为高层设计起点完全可以接受，因为它先满足了用户能找到活动的功能需求；至于它在规模上不够好，后面再通过全文索引、专用搜索引擎和缓存继续优化。</p><h4 id="三、用户能够购买门票" tabindex="-1">三、用户能够购买门票 <a class="header-anchor" href="#三、用户能够购买门票" aria-label="Permalink to &quot;三、用户能够购买门票&quot;">​</a></h4><p>购票路径是整个系统最重要的部分。最早期的基础版可以这样设计：用户选择若干张票；客户端调用 <code>POST /bookings/{eventId}</code>；<code>Booking Service</code> 开启数据库事务；检查这些票是否仍可用；如果可用，则创建 <code>Booking</code>，并把 <code>Ticket.status</code> 更新；成功后返回 <code>bookingId</code>。这里只要数据库支持事务，理论上就可以避免同一张票被同时卖给两个人。PostgreSQL 是一个常见选择，因为购票路径需要 ACID 事务、行级更新和并发控制。MySQL 或其他支持事务的数据库也可以胜任，重点不是具体名字，而是票务预占和最终售卖这条链路不能只依赖最终一致。</p><h3 id="深入讨论" tabindex="-1">深入讨论 <a class="header-anchor" href="#深入讨论" aria-label="Permalink to &quot;深入讨论&quot;">​</a></h3><h4 id="一、为什么需要预占座位" tabindex="-1">一、为什么需要预占座位 <a class="header-anchor" href="#一、为什么需要预占座位" aria-label="Permalink to &quot;一、为什么需要预占座位&quot;">​</a></h4><p>如果系统只在最终提交支付时才检查票是否还在，用户体验会很不稳定：用户挑好票，填了很久支付信息，最后才被告知票已经被别人买走。因此，票务系统通常需要引入“预占座位”的概念。</p><h4 id="二、几种常见预占方案" tabindex="-1">二、几种常见预占方案 <a class="header-anchor" href="#二、几种常见预占方案" aria-label="Permalink to &quot;二、几种常见预占方案&quot;">​</a></h4><h5 id="长事务数据库锁" tabindex="-1">长事务数据库锁 <a class="header-anchor" href="#长事务数据库锁" aria-label="Permalink to &quot;长事务数据库锁&quot;">​</a></h5><p>一个直接的做法，是使用 <code>SELECT ... FOR UPDATE</code>：用户点中座位后，系统锁住对应行，等待用户在 5 分钟内完成支付。这个方案听起来直接，但问题很明显：数据库锁不适合持有几分钟；高并发下会制造严重锁竞争；用户放弃支付、网络中断、应用崩溃都很难优雅处理。因此，长时间数据库锁不适合作为票务预占方案。</p><h5 id="状态-过期时间-定时任务" tabindex="-1">状态 + 过期时间 + 定时任务 <a class="header-anchor" href="#状态-过期时间-定时任务" aria-label="Permalink to &quot;状态 + 过期时间 + 定时任务&quot;">​</a></h5><p>更稳妥的做法是给 <code>Ticket</code> 增加 <code>status</code> 和 <code>reservationExpiresAt</code>。当用户选中座位时，将状态从 <code>available</code> 改为 <code>reserved</code>，同时写入过期时间，例如 <code>now + 10 minutes</code>。如果用户完成支付，状态变为 <code>sold</code>；如果用户超时放弃，系统再把它恢复成 <code>available</code>。一个简单实现方式是用 cron 周期性扫描过期预占，再释放它们。但这个方案仍然有缺点：过期释放不是实时的，cron 出故障会导致大量票长时间被错误占住。</p><h5 id="隐式状态-短事务" tabindex="-1">隐式状态 + 短事务 <a class="header-anchor" href="#隐式状态-短事务" aria-label="Permalink to &quot;隐式状态 + 短事务&quot;">​</a></h5><p>更好的思路是把“是否可预占”判断为 <code>available</code> 或者 <code>reserved</code> 但 <code>reservationExpiresAt</code> 已经过期。也就是说，系统不需要真的等 cron 把状态改回去，任何新的预占事务都可以把“已过期的 reserved”当成可抢占目标。于是事务就可以非常短：开启事务，检查该票是否 <code>available</code> 或 <code>reserved but expired</code>，如果是则把它更新成 <code>reserved + new expiration</code>，提交事务。这样既保留了数据库的一致性保证，又避免了长事务锁。</p><h4 id="三、为什么-redis-在这里仍然有价值" tabindex="-1">三、为什么 Redis 在这里仍然有价值 <a class="header-anchor" href="#三、为什么-redis-在这里仍然有价值" aria-label="Permalink to &quot;三、为什么 Redis 在这里仍然有价值&quot;">​</a></h4><p>即使 PostgreSQL 已经能保证强一致，Redis 仍然很有帮助，因为这里还有一个“自动到期”的需求。数据库可以做事务，但天然不擅长做“高并发下的临时占位 + 精确过期释放”。Redis 则很适合承担短期 reservation 状态：键过期是原生能力，内存操作延迟低，高并发下抢占速度更快。因此一个常见演进是持久化事实仍在 PostgreSQL，短期 reservation 锁放在 Redis，再配合最终支付确认时回写数据库。这样既保留了数据库里的最终事实，也把高频、短期、可过期的预占状态交给了更合适的存储。</p><h4 id="四、如何扩展活动查看路径" tabindex="-1">四、如何扩展活动查看路径 <a class="header-anchor" href="#四、如何扩展活动查看路径" aria-label="Permalink to &quot;四、如何扩展活动查看路径&quot;">​</a></h4><p>当热门活动开票时，活动页会被频繁刷新。这里最大的压力其实不在购票事务，而在读流量，包括活动名称、时间、艺人介绍、场馆信息、seat map 和当前剩余票状态。其中很多信息是高读低写的，非常适合缓存。核心思路是对 <code>Event</code>、<code>Performer</code>、静态 <code>Venue</code> 信息做激进缓存，<code>Event Service</code> 做水平扩容，前面用负载均衡均匀分发请求。具体来说，<code>eventId -&gt; eventObject</code> 很适合放 Redis / Memcached，静态元数据 TTL 可以较长，票务状态 TTL 应更短，或者走局部失效。这条链路体现的是一个典型原则：一致性重的路径单独保守设计，读多写少的路径尽量通过缓存和水平扩容减压。</p><h4 id="五、热门活动里-为什么仅靠实时-seat-map-更新还不够" tabindex="-1">五、热门活动里，为什么仅靠实时 seat map 更新还不够 <a class="header-anchor" href="#五、热门活动里-为什么仅靠实时-seat-map-更新还不够" aria-label="Permalink to &quot;五、热门活动里，为什么仅靠实时 seat map 更新还不够&quot;">​</a></h4><p>一个自然的改法，是在活动页打开后用 SSE 持续把座位变化推给客户端：某张票被预占或卖出，马上通知正在看这个 seat map 的用户。这比让用户手动刷新强很多，也更符合产品体验。但在极端热门活动里，例如超大明星演出，这个方案还是不够：用户会看到座位瞬间成片消失，页面不断刷新状态，大量用户仍在同时争抢同一小批票。也就是说，实时更新能改善信息滞后，却不能从根本上降低竞争强度。</p><h4 id="六、极端热点活动的更优体验-虚拟排队" tabindex="-1">六、极端热点活动的更优体验：虚拟排队 <a class="header-anchor" href="#六、极端热点活动的更优体验-虚拟排队" aria-label="Permalink to &quot;六、极端热点活动的更优体验：虚拟排队&quot;">​</a></h4><p>对超热点活动，更合适的产品化思路是启用 virtual waiting room。核心做法是：用户想进入购票页时，不立即放他进 seat map，而是先把用户放进等待队列；通过 SSE 或 WebSocket 持续告知排队位置；系统按节奏逐步放用户进入购票页；只有被放行的用户，才允许真正发起 reservation / booking。</p><p>这个队列可以放在 Redis 里，例如用 sorted set 存排队顺序，再用一个带 TTL 的 <code>admitted:{eventId}</code> 集合记录被放行用户。然后 <code>Booking Service</code> 在处理 reservation 请求前，先检查当前用户是否已被 waiting room 放行，如果没有就直接拒绝。这个方案的重要性在于，它不是在“更快地抢”，而是在“减少无意义竞争”，从产品体验和系统稳定性两个维度一起降压。</p><h4 id="七、搜索为什么不能只靠-sql-like" tabindex="-1">七、搜索为什么不能只靠 SQL LIKE <a class="header-anchor" href="#七、搜索为什么不能只靠-sql-like" aria-label="Permalink to &quot;七、搜索为什么不能只靠 SQL LIKE&quot;">​</a></h4><p>基础搜索通常会写成 <code>SELECT * FROM Events WHERE name LIKE &#39;%Taylor%&#39; OR description LIKE &#39;%Taylor%&#39;;</code>，这在数据量大时会很慢，因为 <code>%keyword%</code> 往往意味着全表扫描。第一步优化可以是给常用过滤列建索引，做 SQL 优化，用 <code>LIMIT</code>，拆 <code>OR</code> 为更友好的查询形式，但它对模糊关键词搜索仍然不够好。</p><p>更进一步的两种方案是：数据库内全文索引，例如 PostgreSQL 的 <code>tsvector + GIN</code>，优点是不引入额外系统，比 <code>%LIKE%</code> 快很多，缺点是维护和查询仍然会比普通索引复杂，模糊匹配、纠错等能力有限；外挂全文搜索引擎，例如 Elasticsearch，更适合关键词搜索多、需要 typo tolerance 和更复杂的全文检索能力，但代价是要维护额外集群，要做 SQL -&gt; ES 的 CDC 同步。因此，搜索链路不必一开始就绑定 Elasticsearch：规模较小时可以用数据库索引或 DB 内全文搜索，复杂搜索要求上来后再演进到专用搜索引擎。</p><h4 id="八、如何缓存热门搜索结果" tabindex="-1">八、如何缓存热门搜索结果 <a class="header-anchor" href="#八、如何缓存热门搜索结果" aria-label="Permalink to &quot;八、如何缓存热门搜索结果&quot;">​</a></h4><p>Ticketmaster 的搜索还存在另一个很典型的问题：热门艺人、热门城市、热门日期组合会被反复搜索，这非常适合结果缓存。例如缓存 key 可以长成 <code>search:keyword=Taylor Swift&amp;start=2026-05-01&amp;end=2026-12-31</code>，然后把对应活动列表缓存一段时间。如果搜索结果不带个性化，还可以继续往前推一层，使用 CDN 或 edge cache，这样很多热门搜索甚至不需要每次都打到搜索服务本体。</p><h3 id="整体链路" tabindex="-1">整体链路 <a class="header-anchor" href="#整体链路" aria-label="Permalink to &quot;整体链路&quot;">​</a></h3><h4 id="查看活动路径" tabindex="-1">查看活动路径 <a class="header-anchor" href="#查看活动路径" aria-label="Permalink to &quot;查看活动路径&quot;">​</a></h4><ol><li>用户请求 <code>GET /events/{eventId}</code></li><li>API Gateway 转给 <code>Event Service</code></li><li>服务优先命中缓存</li><li>未命中则读数据库</li><li>返回活动、场馆、艺人和座位信息</li></ol><h4 id="搜索路径" tabindex="-1">搜索路径 <a class="header-anchor" href="#搜索路径" aria-label="Permalink to &quot;搜索路径&quot;">​</a></h4><ol><li>用户请求 <code>GET /events/search</code></li><li><code>Search Service</code> 先查搜索结果缓存</li><li>未命中时，查询 DB 全文索引或 Elasticsearch</li><li>返回分页结果</li></ol><h4 id="预占与购票路径" tabindex="-1">预占与购票路径 <a class="header-anchor" href="#预占与购票路径" aria-label="Permalink to &quot;预占与购票路径&quot;">​</a></h4><ol><li>用户挑选票</li><li><code>Booking Service</code> 通过短事务把票更新成 <code>reserved</code></li><li>返回 <code>bookingId</code></li><li>用户完成支付</li><li>支付成功 webhook 回来</li><li>系统把 <code>Booking.status</code> 更新为 <code>confirmed</code></li><li>对应 <code>Ticket.status</code> 更新为 <code>sold</code></li></ol><h4 id="热门活动路径" tabindex="-1">热门活动路径 <a class="header-anchor" href="#热门活动路径" aria-label="Permalink to &quot;热门活动路径&quot;">​</a></h4><ol><li>用户尝试进入购票页</li><li>先被放进 virtual waiting room</li><li>通过 SSE 获得排队位置更新</li><li>被放行后才能进入 seat map 和 reservation 流程</li></ol><h2 id="参考来源" tabindex="-1">参考来源 <a class="header-anchor" href="#参考来源" aria-label="Permalink to &quot;参考来源&quot;">​</a></h2><ul><li><a href="https://www.hellointerview.com/learn/system-design/problem-breakdowns/ticketmaster" target="_blank" rel="noreferrer">Hello Interview 官方讲解：Ticketmaster</a></li></ul>',59)])])}const p=a(c,[["render",i]]);export{m as __pageData,p as default};
